// Check if the SessionID collection variable is not found
if (!pm.collectionVariables.has("SessionID")) {
    let url = {
        protocol: pm.request.url.protocol,
        port: pm.request.url.port,
        host: pm.request.url.host,
        path: [pm.request.url.path[0], "REST", "AccountService", "LoginUser"],
        query: [],
        variable: []
    }
    // Run another request from the collection to set the SessionID variable
    pm.sendRequest({
        url: url,
        method: 'POST',
        body: {
            mode: 'raw',
            raw: JSON.stringify({ "userid": pm.variables.get("UserId"), "password": pm.variables.get("Password"), "outputtype": "Json" })
        }}, function (err, response) {
        if (err) {
            console.log(err);
        } else {
            // Extract the SessionValue from the response and store it in the SessionID collection variable
            var sessionValue = response.json().LoginUserResult.SessionValue;
            pm.collectionVariables.set("SessionID", sessionValue);
        }
    });
}

